template.solver:
def solve(k):
    N = 200000
    sieve = [True] * (N + 1)
    sieve[0] = False
    sieve[1] = False
    for i in range(2, int(sqrt(N)) + 1):
        if sieve[i]:
            for j in range(i * i, N + 1, i):
                sieve[j] = False
    primes = [i for i in range(N + 1) if sieve[i]]
    best = 0
    for n in range(1, len(primes) + 1):
        if k * n >= primes[n - 1]:
            best = n
    return best
